package service

import (
	"errors"
	"strings"

	"lms/backend/internal/models"
)

// ListBooks 查询图书。
func (s *Service) ListBooks(keyword string, categoryID *int64) ([]models.Book, error) {
	return s.repo.ListBooks(strings.TrimSpace(keyword), categoryID)
}

// AddBook 新增图书。
func (s *Service) AddBook(actor *models.User, b *models.Book) error {
	b.Title = strings.TrimSpace(b.Title)
	if b.Title == "" {
		return Error("书名不能为空")
	}
	if b.TotalQty < 1 {
		return Error("馆藏数量至少为 1")
	}
	if err := s.repo.CreateBook(b); err != nil {
		return Error("新增图书失败")
	}
	return s.log(actor.ID, actor.Username, "新增图书", b.Title)
}

// UpdateBook 修改图书。
func (s *Service) UpdateBook(actor *models.User, b *models.Book) error {
	b.Title = strings.TrimSpace(b.Title)
	if b.Title == "" {
		return Error("书名不能为空")
	}
	old, err := s.repo.GetBook(b.ID)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return Error("图书不存在")
		}
		return err
	}
	borrowed := old.TotalQty - old.AvailableQty
	if err := checkTotalQty(b.TotalQty, borrowed); err != nil {
		return err
	}
	if err := s.repo.UpdateBook(b); err != nil {
		return Error("修改图书失败")
	}
	return s.log(actor.ID, actor.Username, "修改图书", b.Title)
}

// DeleteBook 删除图书（存在在借记录时拒绝）。
func (s *Service) DeleteBook(actor *models.User, id int64) error {
	book, err := s.repo.GetBook(id)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return Error("图书不存在")
		}
		return err
	}
	n, err := s.repo.CountActiveBorrowsForBook(id)
	if err != nil {
		return err
	}
	if n > 0 {
		return Error("该图书存在未归还的借阅记录，无法删除")
	}
	if err := s.repo.DeleteBook(id); err != nil {
		return Error("删除图书失败")
	}
	return s.log(actor.ID, actor.Username, "删除图书", book.Title)
}

package service

import (
	"errors"
	"strconv"
	"time"

	"lms/backend/internal/models"
)

// Borrow 管理员为读者办理借阅。
func (s *Service) Borrow(actor *models.User, readerID, bookID int64) error {
	reader, err := s.repo.GetReaderByID(readerID)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return Error("读者不存在")
		}
		return err
	}
	book, err := s.repo.GetBook(bookID)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return Error("图书不存在")
		}
		return err
	}
	today := time.Now()
	todayStr := today.Format(dateLayout)
	active, err := s.repo.CountActive(readerID)
	if err != nil {
		return err
	}
	overdue, err := s.repo.CountOverdue(readerID, todayStr)
	if err != nil {
		return err
	}
	if err := checkBorrow(book.AvailableQty, active, overdue); err != nil {
		return err
	}
	rec := &models.BorrowRecord{
		ReaderID:   readerID,
		BookID:     bookID,
		BorrowDate: todayStr,
		DueDate:    today.AddDate(0, 0, LoanDays).Format(dateLayout),
		Status:     "borrowed",
	}
	if err := s.repo.CreateBorrow(rec); err != nil {
		return Error("办理借阅失败")
	}
	if err := s.repo.DecAvailable(bookID); err != nil {
		return err
	}
	return s.log(actor.ID, actor.Username, "借阅图书",
		reader.Name+" 借阅《"+book.Title+"》")
}

// SelfBorrow 读者自助借阅。
func (s *Service) SelfBorrow(actor *models.User, bookID int64) error {
	reader, err := s.repo.GetReaderByUserID(actor.ID)
	if err != nil {
		return Error("读者档案不存在")
	}
	return s.Borrow(actor, reader.ID, bookID)
}

// Renew 办理续借；ownerReaderID 非 nil 时校验记录归属（读者自助场景）。
func (s *Service) Renew(actor *models.User, recordID int64, ownerReaderID *int64) error {
	rec, err := s.repo.GetBorrow(recordID)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return Error("借阅记录不存在")
		}
		return err
	}
	if rec.Status != "borrowed" {
		return Error("该记录已归还，无需续借")
	}
	if ownerReaderID != nil && rec.ReaderID != *ownerReaderID {
		return Error("只能续借本人的图书")
	}
	todayStr := time.Now().Format(dateLayout)
	if err := checkRenew(rec.RenewCount, rec.DueDate, todayStr); err != nil {
		return err
	}
	due, _ := time.Parse(dateLayout, rec.DueDate)
	newDue := due.AddDate(0, 0, RenewDays).Format(dateLayout)
	if err := s.repo.MarkRenewed(recordID, newDue, rec.RenewCount+1); err != nil {
		return Error("续借失败")
	}
	return s.log(actor.ID, actor.Username, "续借图书", "《"+rec.Title+"》")
}

// SelfRenew 读者自助续借。
func (s *Service) SelfRenew(actor *models.User, recordID int64) error {
	reader, err := s.repo.GetReaderByUserID(actor.ID)
	if err != nil {
		return Error("读者档案不存在")
	}
	id := reader.ID
	return s.Renew(actor, recordID, &id)
}

// Return 办理归还，返回应缴罚款。
func (s *Service) Return(actor *models.User, recordID int64) (float64, error) {
	rec, err := s.repo.GetBorrow(recordID)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return 0, Error("借阅记录不存在")
		}
		return 0, err
	}
	if rec.Status != "borrowed" {
		return 0, Error("该记录已归还，请勿重复操作")
	}
	todayStr := time.Now().Format(dateLayout)
	fine := calcFine(rec.DueDate, todayStr)
	if err := s.repo.MarkReturned(recordID, todayStr, fine); err != nil {
		return 0, Error("归还失败")
	}
	if err := s.repo.IncAvailable(rec.BookID); err != nil {
		return 0, err
	}
	detail := "归还《" + rec.Title + "》"
	if fine > 0 {
		detail += "，逾期罚款 " + formatFloat(fine) + " 元"
	}
	_ = s.log(actor.ID, actor.Username, "归还图书", detail)
	return fine, nil
}

// ActiveBorrows 查询未归还借阅；readerID 为 nil 时查询全部（管理员）。
func (s *Service) ActiveBorrows(readerID *int64) ([]models.BorrowRecord, error) {
	recs, err := s.repo.ListActive(readerID)
	if err != nil {
		return nil, err
	}
	return annotate(recs), nil
}

// HistoryBorrows 查询已归还历史；readerID 为 nil 时查询全部（管理员）。
func (s *Service) HistoryBorrows(readerID *int64) ([]models.BorrowRecord, error) {
	recs, err := s.repo.ListHistory(readerID)
	if err != nil {
		return nil, err
	}
	return annotate(recs), nil
}

// MyReader 返回当前登录用户对应的读者档案。
func (s *Service) MyReader(actor *models.User) (*models.Reader, error) {
	r, err := s.repo.GetReaderByUserID(actor.ID)
	if err != nil {
		return nil, Error("读者档案不存在")
	}
	return r, nil
}

func formatFloat(f float64) string {
	return strconv.FormatFloat(f, 'f', 2, 64)
}

package service_test

import (
	"os"
	"path/filepath"
	"testing"

	"lms/backend/internal/models"
	"lms/backend/internal/service"
	"lms/backend/internal/store"
)

// newSvc 创建基于临时数据库的服务（测试结束自动清理）。
func newSvc(t *testing.T) (*service.Service, func()) {
	t.Helper()
	dir := t.TempDir()
	dbPath := filepath.Join(dir, "test.db")
	st, err := store.New(dbPath)
	if err != nil {
		t.Fatalf("初始化测试库失败: %v", err)
	}
	return service.New(st), func() { _ = st.Close(); _ = os.Remove(dbPath) }
}

func admin() *models.User { return &models.User{ID: 1, Username: "admin", Role: "admin", RealName: "系统管理员"} }

func TestLoginFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	if _, err := svc.Login("admin", "admin123"); err != nil {
		t.Fatalf("管理员登录失败: %v", err)
	}
	if _, err := svc.Login("admin", "wrong"); err == nil {
		t.Fatal("错误口令应登录失败")
	}
	if _, err := svc.Login("nobody", "x"); err == nil {
		t.Fatal("不存在用户应登录失败")
	}
}

func TestRegisterFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	no, err := svc.Register("tuser", "test123", "测试读者", "13900000000")
	if err != nil {
		t.Fatalf("注册失败: %v", err)
	}
	if no == "" {
		t.Fatal("应返回读者编号")
	}
	if _, err := svc.Register("tuser", "test123", "重复", ""); err == nil {
		t.Fatal("重复用户名应失败")
	}
	if _, err := svc.Register("u2", "123", "短口令", ""); err == nil {
		t.Fatal("短口令应失败")
	}
	if _, err := svc.Login("tuser", "test123"); err != nil {
		t.Fatalf("新读者登录失败: %v", err)
	}
}

func TestBorrowLimitFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	no, _ := svc.Register("limit", "test123", "限借读者", "")
	_ = no
	// 找到该读者
	u, _ := svc.Login("limit", "test123")
	rd, err := svc.MyReader(u)
	if err != nil {
		t.Fatal(err)
	}
	books, _ := svc.ListBooks("", nil)
	avail := []models.Book{}
	for _, b := range books {
		if b.AvailableQty > 0 {
			avail = append(avail, b)
		}
	}
	for i := 0; i < service.MaxBorrow; i++ {
		if err := svc.Borrow(admin(), rd.ID, avail[i].ID); err != nil {
			t.Fatalf("第 %d 本借阅失败: %v", i+1, err)
		}
	}
	active, _ := svc.ActiveBorrows(&rd.ID)
	if len(active) != service.MaxBorrow {
		t.Fatalf("在借数量期望 %d，实际 %d", service.MaxBorrow, len(active))
	}
	if err := svc.Borrow(admin(), rd.ID, avail[service.MaxBorrow].ID); err == nil {
		t.Fatal("超过上限应拒绝借阅")
	}
}

func TestRenewFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	svc.Register("renewu", "test123", "续借读者", "")
	u, _ := svc.Login("renewu", "test123")
	rd, _ := svc.MyReader(u)
	books, _ := svc.ListBooks("", nil)
	var bookID int64
	for _, b := range books {
		if b.AvailableQty > 0 {
			bookID = b.ID
			break
		}
	}
	if err := svc.Borrow(admin(), rd.ID, bookID); err != nil {
		t.Fatal(err)
	}
	active, _ := svc.ActiveBorrows(&rd.ID)
	recID := active[0].ID
	if err := svc.SelfRenew(u, recID); err != nil {
		t.Fatalf("首次续借失败: %v", err)
	}
	active, _ = svc.ActiveBorrows(&rd.ID)
	if active[0].RenewCount != 1 {
		t.Fatal("续借次数应为 1")
	}
	if err := svc.SelfRenew(u, recID); err == nil {
		t.Fatal("二次续借应拒绝")
	}
}

func TestReturnAndFineFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	// 种子读者 reader（含一条逾期借阅：时间简史，40天前借出）
	recs, _ := svc.ActiveBorrows(nil)
	var overdue, normal int64
	for _, r := range recs {
		if r.Title == "时间简史" {
			overdue = r.ID
		}
		if r.Title == "Python编程：从入门到实践" {
			normal = r.ID
		}
	}
	fine, err := svc.Return(admin(), overdue)
	if err != nil {
		t.Fatalf("归还逾期图书失败: %v", err)
	}
	if fine < 4.5 || fine > 5.5 {
		t.Fatalf("逾期约10天罚款应约 5 元，实际 %.2f", fine)
	}
	fine2, err := svc.Return(admin(), normal)
	if err != nil {
		t.Fatalf("归还正常图书失败: %v", err)
	}
	if fine2 != 0 {
		t.Fatalf("未逾期罚款应为 0，实际 %.2f", fine2)
	}
	if _, err := svc.Return(admin(), overdue); err == nil {
		t.Fatal("重复归还应拒绝")
	}
}

func TestDeleteProtectionFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	recs, _ := svc.ActiveBorrows(nil)
	if len(recs) == 0 {
		t.Fatal("种子数据应含在借记录")
	}
	if err := svc.DeleteBook(admin(), recs[0].BookID); err == nil {
		t.Fatal("有在借记录的图书应禁止删除")
	}
}

func TestPasswordFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	u, _ := svc.Login("reader", "reader123")
	if err := svc.ChangePassword(u.ID, "wrong", "newpass1"); err == nil {
		t.Fatal("原口令错误应失败")
	}
	if err := svc.ChangePassword(u.ID, "reader123", "newpass1"); err != nil {
		t.Fatalf("改密失败: %v", err)
	}
	if _, err := svc.Login("reader", "newpass1"); err != nil {
		t.Fatal("新口令应可登录")
	}
}

func TestStatsFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	d, err := svc.Dashboard()
	if err != nil {
		t.Fatal(err)
	}
	if d.BookKinds < 10 {
		t.Fatalf("图书种类应 >=10，实际 %d", d.BookKinds)
	}
	if d.Readers < 1 {
		t.Fatal("应至少有1名种子读者")
	}
	if d.Overdue < 1 {
		t.Fatal("种子数据应含1本逾期")
	}
	cats, _ := svc.CategoryStats()
	if len(cats) < 6 {
		t.Fatal("分类统计应 >=6")
	}
	hot, _ := svc.HotBooks()
	if len(hot) < 5 {
		t.Fatal("热门图书应 >=5")
	}
	if _, err := svc.Login("admin", "admin123"); err != nil {
		t.Fatal(err)
	}
	logs, _ := svc.RecentLogs()
	if len(logs) == 0 {
		t.Fatal("操作日志应非空")
	}
}

func TestDisableFlow(t *testing.T) {
	svc, cleanup := newSvc(t)
	defer cleanup()

	u, _ := svc.Login("reader", "reader123")
	if err := svc.SetReaderStatus(admin(), u.ID, "disabled"); err != nil {
		t.Fatal(err)
	}
	if _, err := svc.Login("reader", "reader123"); err == nil {
		t.Fatal("停用账号应无法登录")
	}
	if err := svc.SetReaderStatus(admin(), u.ID, "active"); err != nil {
		t.Fatal(err)
	}
	if _, err := svc.Login("reader", "reader123"); err != nil {
		t.Fatal("重新启用后应可登录")
	}
}

package service

import (
	"strconv"
	"time"

	"lms/backend/internal/models"
)

// 本文件集中放置纯业务规则判定函数，无 I/O 依赖，便于单元测试与复用（高内聚）。

const dateLayout = "2006-01-02"

// checkBorrow 判定是否允许借阅：库存、在借上限、逾期三个条件。
func checkBorrow(available, activeCount, overdueCount int) error {
	switch {
	case available <= 0:
		return Error("该图书暂无在馆库存")
	case activeCount >= MaxBorrow:
		return Error("在借图书已达上限（5 本），请先归还")
	case overdueCount > 0:
		return Error("您有逾期未还的图书，请先归还后再借阅")
	}
	return nil
}

// checkRenew 判定是否允许续借：续借次数与是否逾期。
func checkRenew(renewCount int, dueDate, today string) error {
	switch {
	case renewCount >= MaxRenew:
		return Error("该图书已续借 1 次，无法再次续借")
	case dueDate < today:
		return Error("图书已逾期，无法续借，请先归还")
	}
	return nil
}

// checkTotalQty 判定修改馆藏数量时不能小于已借出数量。
func checkTotalQty(totalQty, borrowed int) error {
	if totalQty < borrowed {
		return Error("馆藏数量不能小于当前已借出数量")
	}
	return nil
}

// calcFine 按应还日期与实际归还日期计算逾期罚款；未逾期为 0。
func calcFine(dueDate, returnDate string) float64 {
	due, err1 := time.Parse(dateLayout, dueDate)
	ret, err2 := time.Parse(dateLayout, returnDate)
	if err1 != nil || err2 != nil {
		return 0
	}
	if !ret.After(due) {
		return 0
	}
	return float64(ret.Sub(due).Hours()/24) * FinePerDay
}

// stateText 根据状态与应还日期动态生成借阅状态文本。
func stateText(rec models.BorrowRecord, today time.Time) string {
	if rec.Status == "returned" {
		return "已归还"
	}
	due, err := time.Parse(dateLayout, rec.DueDate)
	if err != nil {
		return rec.Status
	}
	// 按日历日计算差值（统一取当天零点），避免当天时刻导致天数少算
	nowDay := time.Date(today.Year(), today.Month(), today.Day(), 0, 0, 0, 0, time.Local)
	dueDay := time.Date(due.Year(), due.Month(), due.Day(), 0, 0, 0, 0, time.Local)
	days := int(dueDay.Sub(nowDay).Hours() / 24)
	if days < 0 {
		return "已逾期 " + strconv.Itoa(-days) + " 天"
	}
	return "借阅中（剩 " + strconv.Itoa(days) + " 天）"
}

// annotate 为借阅记录批量填充动态状态字段。
func annotate(recs []models.BorrowRecord) []models.BorrowRecord {
	today := time.Now()
	for i := range recs {
		recs[i].State = stateText(recs[i], today)
	}
	return recs
}
